const raw = $input.first().json.content?.parts?.[0]?.text ?? '';
const clean = raw.replace(/^\s*\x60\x60\x60(?:json)?/i, '').replace(/\x60\x60\x60\s*$/i, '').trim();
const story = JSON.parse(clean);
const moods=new Set(['happy','playful','adventure','curious','calm','gentle','celebration']);
if (!story.title || !moods.has(story.music_mood) || !Array.isArray(story.scenes) || story.scenes.length === 0) throw new Error('Gemini returned an invalid story schema');
const lineTypes=new Set(['narration','dialogue']);
for (const [index, scene] of story.scenes.entries()) {
  if (!scene.location_id || !scene.image_prompt || !Array.isArray(scene.dialogue_lines) || !scene.dialogue_lines.length || !Array.isArray(scene.characters) || !scene.characters.length) throw new Error('Scene ' + (index + 1) + ' is incomplete');
  const locations=new Set(['kiko_home_living_room','kiko_bedroom','classroom','playground','neighborhood_street','village_park','gentle_forest']); if(!locations.has(scene.location_id)) throw new Error('Scene '+(index+1)+' has invalid location_id');
  const sfx=new Set(['none','footsteps_grass','footsteps_wood','footsteps_concrete','soft_bell','light_impact','click','switch']); if(!sfx.has(scene.sfx_cue)) throw new Error('Scene '+(index+1)+' has invalid sfx_cue');
  const ids=new Set(['kiko','lala','bimo','nara','toto']); const expressions=new Set(['happy','excited','curious','surprised','worried','sad','thinking','laughing','sleeping','child_safe_angry']); const poses=new Set(['neutral','waving','pointing','running','helping','celebrating','listening','sitting','thinking','sleeping']);
  for(const c of scene.characters){if(!ids.has(c.character_id)||!expressions.has(c.expression)||!poses.has(c.pose)) throw new Error('Scene '+(index+1)+' has invalid character direction');}
  const sceneSpeakers=new Set(['narrator',...scene.characters.map(c=>c.character_id)]);
  for(const [lineIndex, line] of scene.dialogue_lines.entries()){
    if(!line || typeof line.text !== 'string' || !line.text.trim() || typeof line.text_en !== 'string' || !line.text_en.trim()) throw new Error('Scene '+(index+1)+' dialogue_lines['+lineIndex+'] must have non-empty text and text_en');
    if(!sceneSpeakers.has(line.speaker)) throw new Error('Scene '+(index+1)+' dialogue_lines['+lineIndex+'] has unknown speaker: '+line.speaker);
    if(!lineTypes.has(line.line_type)) throw new Error('Scene '+(index+1)+' dialogue_lines['+lineIndex+'] has invalid line_type');
  }
  scene.narration = scene.dialogue_lines.map(l=>l.text.trim()).join(' ');
  scene.narration_en = scene.dialogue_lines.map(l=>l.text_en.trim()).join(' ');
  scene.scene_number = Number(scene.scene_number ?? index + 1);
}
const input = $('Edit Fields').first().json;
const libraries=$('Select Reusable Libraries').first().json;
return [{json:{episode_id:input.episode_id,theme:input.theme,target_age:input.target_age,language:'id',title:story.title,music_mood:story.music_mood,story_template:libraries.story_template,animation_preset:libraries.animation_preset,thumbnail_template:libraries.thumbnail_template,scenes:story.scenes}}];
